  Exercise(id:"python-c0-t1-classwork-1-v1", topic:"python-c0-t1", category:"Classwork", type:"code", title:"Two messages and a comment", prompt:"Display System Initialized and Connection secure. on separate lines, in that order. Include a source comment describing the demonstration.", tests:[{"input":[],"expected":"System Initialized\nConnection secure.","harness":"import tokenize,io\nassert any(t.type==tokenize.COMMENT for t in tokenize.generate_tokens(io.StringIO(_academy_source).readline)), 'Include an explanatory source comment.'","comparison":"normalized"}], hints:["Count the required output lines."], required:false, filename:"learner.py", solution:"# Mock status\nprint(\"System Initialized\")\nprint(\"Connection secure.\")\n\nOne valid implementation. Compare the result with every supplied case."),
