List<Exercise> get exercises => [...starterExercises, ...extendedExercises, ...completedExercises];
List<Exercise> forTopic(String topic, String category) => exercises.where((e) => e.topic == topic && e.category == category).toList();

String workspaceFilename(Topic topic, String category, {String activity = '', bool code = true}) {
  String slug(String text) => text.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '-').replaceAll(RegExp(r'^-+|-+$'), '');
  final parts=[slug(topic.title),slug(category),if(activity.isNotEmpty)slug(activity)];
  final name=parts.where((part)=>part.isNotEmpty).join('-');
  return '${name.length>170?name.substring(0,170):name}.${code?'py':'txt'}';
}
